css:
.aguarales-sim-container {
    padding: 28px;
    background: linear-gradient(180deg, #f5f1e8 0%, #ece4d3 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    color: #1a1a1a;
    line-height: 1.5;
}

.aguarales-sim-container h1,
.aguarales-sim-container h3 {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    letter-spacing: 0.01em;
}

/* Header */
.aguarales-sim-header {
    display: grid;
    grid-template-columns: auto 1fr auto;
    gap: 24px;
    align-items: center;
    background: linear-gradient(135deg, #1a2744 0%, #243762 100%);
    color: #f5f1e8;
    padding: 28px 32px;
    border-radius: 6px;
    border-bottom: 4px solid #c9a961;
    margin-bottom: 24px;
    box-shadow: 0 8px 24px rgba(26,39,68,0.18);
}
.aguarales-sim-seal {
    font-size: 3rem;
    font-weight: 300;
    color: #c9a961;
    line-height: 1;
    width: 64px;
    height: 64px;
    border: 2px solid #c9a961;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}
.aguarales-sim-header h1 {
    font-size: 1.6rem;
    font-weight: 600;
    margin: 0 0 4px 0;
    color: #f5f1e8;
}
.aguarales-sim-subtitle {
    font-size: 0.9rem;
    color: #c9a961;
    font-style: italic;
    letter-spacing: 0.02em;
}
.aguarales-sim-helena-badge {
    text-align: right;
    border-left: 1px solid rgba(201,169,97,0.4);
    padding-left: 20px;
}
.aguarales-sim-helena-name {
    font-size: 0.92rem;
    font-weight: 600;
    color: #f5f1e8;
}
.aguarales-sim-helena-role {
    font-size: 0.72rem;
    color: #c9a961;
    margin-top: 2px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

/* Period bar */
.aguarales-sim-period-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fffaf0;
    border: 1px solid #d9c89e;
    border-left: 4px solid #7d2027;
    padding: 14px 22px;
    border-radius: 4px;
    margin-bottom: 24px;
    font-size: 0.9rem;
}
.aguarales-sim-period-bar-left {
    display: flex;
    gap: 16px;
    align-items: center;
    flex-wrap: wrap;
}
.aguarales-sim-pill {
    background: #1a2744;
    color: #f5f1e8;
    padding: 6px 14px;
    border-radius: 20px;
    font-size: 0.8rem;
    letter-spacing: 0.04em;
}
.aguarales-sim-pill strong {
    color: #c9a961;
    margin: 0 2px;
    font-weight: 700;
}
.aguarales-sim-pill-of {
    opacity: 0.6;
    font-size: 0.72rem;
}
.aguarales-sim-pill-question {
    background: #7d2027;
}
.aguarales-sim-round-name {
    font-style: italic;
    color: #5a4a2a;
    text-transform: uppercase;
    font-size: 0.78rem;
    letter-spacing: 0.1em;
    font-weight: 600;
}
.aguarales-sim-period-bar-right {
    color: #5a4a2a;
    font-size: 0.85rem;
}
.aguarales-sim-period-bar-right strong {
    color: #1a2744;
    font-weight: 700;
}

/* KPI cards */
.aguarales-sim-status-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.aguarales-sim-status-card {
    background: #fffaf0;
    border: 1px solid #d9c89e;
    border-radius: 6px;
    padding: 18px 20px;
    border-top: 3px solid #1a2744;
    box-shadow: 0 2px 6px rgba(26,39,68,0.06);
}
.aguarales-sim-status-tradition { border-top-color: #1a2744; }
.aguarales-sim-status-consistency { border-top-color: #2d6a4f; }
.aguarales-sim-status-realism { border-top-color: #7d2027; }
.aguarales-sim-status-honesty { border-top-color: #c9a961; }

.aguarales-sim-status-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #5a4a2a;
    font-weight: 600;
    margin-bottom: 8px;
}
.aguarales-sim-status-value {
    font-size: 1.9rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.1;
}
.aguarales-sim-status-tradition .aguarales-sim-status-value {
    font-size: 1.05rem;
    line-height: 1.3;
    padding-top: 6px;
}

/* Briefing */
.aguarales-sim-briefing {
    background: #fffaf0;
    border: 1px solid #d9c89e;
    border-radius: 6px;
    padding: 24px 28px;
    margin-bottom: 24px;
    position: relative;
    box-shadow: 0 4px 14px rgba(26,39,68,0.08);
}
.aguarales-sim-briefing::before {
    content: '';
    position: absolute;
    top: 0; left: 0;
    width: 4px; bottom: 0;
    background: linear-gradient(180deg, #1a2744, #c9a961);
    border-radius: 6px 0 0 6px;
}
.aguarales-sim-briefing-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
    flex-wrap: wrap;
}
.aguarales-sim-briefing-tag {
    background: #7d2027;
    color: #fffaf0;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    padding: 4px 10px;
    border-radius: 3px;
    font-weight: 600;
}
.aguarales-sim-briefing-question {
    font-size: 1.1rem;
    font-weight: 600;
    color: #1a2744;
}
.aguarales-sim-briefing-body {
    font-size: 0.95rem;
    color: #2a2a2a;
    line-height: 1.6;
    margin-bottom: 14px;
}
.aguarales-sim-briefing-quote {
    border-left: 3px solid #c9a961;
    padding: 8px 16px;
    font-style: italic;
    color: #5a4a2a;
    background: rgba(201,169,97,0.08);
    font-size: 0.92rem;
    border-radius: 0 4px 4px 0;
}

/* Controls */
.aguarales-sim-controls {
    background: #fffaf0;
    border: 1px solid #d9c89e;
    border-radius: 6px;
    padding: 24px 28px;
    margin-bottom: 24px;
    box-shadow: 0 4px 14px rgba(26,39,68,0.06);
}
.aguarales-sim-controls h3 {
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #1a2744;
    margin: 0 0 18px 0;
    border-bottom: 1px solid #d9c89e;
    padding-bottom: 10px;
    font-weight: 700;
}
.aguarales-sim-tradition-picker {
    margin-bottom: 22px;
    padding-bottom: 22px;
    border-bottom: 1px dashed #d9c89e;
}
.aguarales-sim-tradition-picker label,
.aguarales-sim-articles > label {
    display: block;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #5a4a2a;
    font-weight: 600;
    margin-bottom: 8px;
}
.aguarales-sim-controls select,
.aguarales-sim-controls input[type="text"],
.aguarales-sim-controls input[type="number"] {
    background: #ffffff;
    border: 1px solid #b8a574;
    color: #1a1a1a;
    border-radius: 4px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.95rem;
    font-family: inherit;
}
.aguarales-sim-controls select option {
    background: #ffffff;
    color: #1a1a1a;
}
.aguarales-sim-controls select:focus,
.aguarales-sim-controls input:focus {
    outline: none;
    border-color: #1a2744;
    box-shadow: 0 0 0 3px rgba(26,39,68,0.12);
}
.aguarales-sim-tradition-note {
    margin-top: 8px;
    font-size: 0.78rem;
    color: #7d2027;
    font-style: italic;
}

/* Article options */
.aguarales-sim-article-options {
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.aguarales-sim-article-option {
    display: flex;
    gap: 12px;
    background: #ffffff;
    border: 1px solid #d9c89e;
    border-radius: 5px;
    padding: 14px 16px;
    cursor: pointer;
    transition: border-color 0.2s ease, background 0.2s ease, transform 0.15s ease;
}
.aguarales-sim-article-option:hover {
    border-color: #1a2744;
    background: #fffdf6;
}
.aguarales-sim-article-option input[type="radio"] {
    margin-top: 4px;
    accent-color: #1a2744;
    flex-shrink: 0;
}
.aguarales-sim-article-option-content {
    flex: 1;
}
.aguarales-sim-article-option-tag {
    display: inline-block;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #1a2744;
    background: rgba(201,169,97,0.18);
    padding: 2px 8px;
    border-radius: 3px;
    margin-bottom: 6px;
    font-weight: 600;
}
.aguarales-sim-article-option-text {
    font-size: 0.92rem;
    color: #2a2a2a;
    line-height: 1.55;
}
.aguarales-sim-article-option.selected {
    border-color: #7d2027;
    background: #fff6f5;
    box-shadow: 0 2px 8px rgba(125,32,39,0.12);
}

/* Trade-off */
.aguarales-sim-tradeoff {
    margin-top: 20px;
    padding: 14px 16px;
    background: rgba(201,169,97,0.1);
    border: 1px solid rgba(201,169,97,0.4);
    border-radius: 5px;
}
.aguarales-sim-tradeoff-label {
    display: flex;
    gap: 10px;
    align-items: flex-start;
    cursor: pointer;
    font-size: 0.92rem;
    color: #1a2744;
    font-weight: 500;
    margin-bottom: 4px;
}
.aguarales-sim-tradeoff-label input {
    margin-top: 4px;
    accent-color: #7d2027;
}
.aguarales-sim-tradeoff-hint {
    font-size: 0.78rem;
    color: #5a4a2a;
    margin-left: 28px;
    font-style: italic;
}

/* Buttons */
.aguarales-sim-buttons {
    display: flex;
    gap: 12px;
    margin-top: 22px;
    align-items: center;
    flex-wrap: wrap;
}
.aguarales-sim-buttons .btn-primary {
    background: #7d2027;
    border-color: #7d2027;
    color: #fffaf0;
    padding: 12px 28px;
    font-size: 0.92rem;
    font-weight: 600;
    border-radius: 4px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    transition: background 0.2s ease, transform 0.15s ease;
}
.aguarales-sim-buttons .btn-primary:hover:not(:disabled) {
    background: #5e1820;
    border-color: #5e1820;
    transform: translateY(-1px);
}
.aguarales-sim-buttons .btn-primary:disabled {
    background: #b88a8d;
    border-color: #b88a8d;
    cursor: not-allowed;
}
.aguarales-sim-buttons .btn-outline-secondary {
    border-color: #1a2744;
    color: #1a2744;
    padding: 8px 18px;
    font-size: 0.82rem;
    border-radius: 4px;
    background: transparent;
}
.aguarales-sim-buttons .btn-outline-secondary:hover {
    background: #1a2744;
    color: #fffaf0;
}

/* History */
.aguarales-sim-history {
    background: #fffaf0;
    border: 1px solid #d9c89e;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 24px;
    box-shadow: 0 4px 14px rgba(26,39,68,0.06);
}
.aguarales-sim-history h3 {
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #1a2744;
    margin: 0 0 14px 0;
    font-weight: 700;
}
.aguarales-sim-history table {
    margin-bottom: 0;
    font-size: 0.85rem;
    color: #2a2a2a;
}
.aguarales-sim-history th {
    background: #1a2744;
    color: #fffaf0;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border: none;
    padding: 10px 12px;
    font-weight: 600;
}
.aguarales-sim-history td {
    padding: 10px 12px;
    border-color: #ece4d3;
    vertical-align: middle;
}
.aguarales-sim-history tr:nth-child(even) td {
    background: rgba(201,169,97,0.05);
}

/* Chart */
.aguarales-sim-chart {
    background: #fffaf0;
    border: 1px solid #d9c89e;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 24px;
    height: 380px;
    box-shadow: 0 4px 14px rgba(26,39,68,0.06);
}
.aguarales-sim-chart h3 {
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #1a2744;
    margin: 0 0 14px 0;
    font-weight: 700;
}
.aguarales-sim-chart canvas {
    max-height: 300px;
}

/* Mobile */
@media (max-width: 768px) {
    .aguarales-sim-container { padding: 14px; }
    .aguarales-sim-header {
        grid-template-columns: 1fr;
        text-align: center;
        padding: 20px;
    }
    .aguarales-sim-helena-badge {
        border-left: none;
        border-top: 1px solid rgba(201,169,97,0.4);
        padding-left: 0;
        padding-top: 14px;
        text-align: center;
    }
    .aguarales-sim-status-grid { grid-template-columns: 1fr 1fr; }
    .aguarales-sim-status-value { font-size: 1.4rem; }
    .aguarales-sim-status-tradition .aguarales-sim-status-value { font-size: 0.9rem; }
    .aguarales-sim-period-bar {
        flex-direction: column;
        gap: 8px;
        align-items: flex-start;
    }
    .aguarales-sim-buttons { flex-direction: column; align-items: stretch; }
    .aguarales-sim-buttons .btn-primary,
    .aguarales-sim-buttons .btn-outline-secondary { width: 100%; }
    .aguarales-sim-chart { height: auto; }
}

/* --- a11y + end-of-run + debrief (added 1.1.0) --- */
.aguarales-sim-article-legend {
    font-weight: 600;
    font-size: 0.9rem;
    margin-bottom: 8px;
}
.aguarales-sim-container button:focus-visible,
.aguarales-sim-container select:focus-visible,
.aguarales-sim-container input:focus-visible,
.aguarales-sim-article-option:focus-within {
    outline: 3px solid #2c3e50;
    outline-offset: 2px;
}
.aguarales-run-complete {
    margin: 14px 0 6px;
    padding: 12px 14px;
    border-left: 4px solid #2c3e50;
    background: #eceff1;
    color: #2c3e50;
    font-weight: 600;
    border-radius: 4px;
}
.aguarales-debrief {
    padding: 18px 20px;
    background: #ffffff;
    border: 1px solid #d5d9dc;
    border-radius: 8px;
    color: #2c3e50;
}
.aguarales-debrief-score { font-size: 2.4rem; font-weight: 700; line-height: 1; }
.aguarales-debrief-score span { font-size: 1.1rem; font-weight: 500; color: #667079; }
.aguarales-debrief-band { font-size: 1.05rem; font-weight: 600; margin-top: 4px; }
.aguarales-debrief-raw, .aguarales-debrief-trad { font-size: 0.9rem; color: #667079; margin-top: 4px; }
.aguarales-debrief-table { width: 100%; margin-top: 14px; border-collapse: collapse; }
.aguarales-debrief-table th,
.aguarales-debrief-table td {
    text-align: left;
    padding: 6px 8px;
    border-bottom: 1px solid #e6e9eb;
    font-size: 0.92rem;
}
.aguarales-debrief-table th { font-weight: 600; color: #45525c; }
.aguarales-debrief h4 { font-size: 0.95rem; margin: 16px 0 6px; }
.aguarales-debrief ul { padding-left: 20px; margin: 0; }
.aguarales-debrief li { font-size: 0.92rem; margin-bottom: 6px; }
@media (prefers-reduced-motion: reduce) {
    .aguarales-sim-container *,
    .aguarales-sim-container *::before,
    .aguarales-sim-container *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}

