                html += '<label class="aguarales-sim-article-option" data-id="' + ids[i] + '">';
                html += '<input type="radio" name="articleChoice" value="' + ids[i] + '" id="articleChoice' + ids[i] + '">';
                html += '<div class="aguarales-sim-article-option-content">';
                html += '<div class="aguarales-sim-article-option-tag">' + tagLabel + '</div>';
                html += '<div class="aguarales-sim-article-option-text">' + t(opt.key) + '</div>';
                html += '</div>';
                html += '</label>';
            }
            container.innerHTML = html;

            // Selected highlight
            var radios = container.querySelectorAll('input[name="articleChoice"]');
            radios.forEach(function(r) {
                r.addEventListener('change', function() {
                    container.querySelectorAll('.aguarales-sim-article-option').forEach(function(lbl) {
                        lbl.classList.remove('selected');
                    });
                    r.closest('.aguarales-sim-article-option').classList.add('selected');
                });
            });
            // Deliberately no pre-selection. The shipped build pre-checked option A, so a
            // player who never touched the options silently submitted the doctrinally pure
            // draft and the article_warning branch in validateDecisions was unreachable.
        }

