        getChartData(state) {
            // A partially restored session can arrive with no domainState at all, and
            // dereferencing it directly throws before the chart draws.
            var ds = (state && state.domainState) ? state.domainState : {};
            var labels = (ds.totalHistory || []).map(function(_, i) { return 'P' + (i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.consistencyHistory || [], label: this._t('consistency_label') },
                        { data: ds.realismHistory || [], label: this._t('realism_label') },
                        { data: ds.honestyHistory || [], label: this._t('honesty_label') },
                        { data: ds.totalHistory || [], label: this._t('chart_total') }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            var h = history || [];
            var consistency = 0, realism = 0, honesty = 0, total = 0;
            var pureCount = 0, hybridCount = 0, evasiveCount = 0, realisticCount = 0;
            var ackCount = 0;

            h.forEach(function(rec) {
                var r = rec.results || {};
                consistency += r.consistency || 0;
                realism += r.realism || 0;
                honesty += r.honesty || 0;
                total += r.roundScore || 0;
                if (r.articleTag === 'pure') pureCount++;
                else if (r.articleTag === 'hybrid') hybridCount++;
                else if (r.articleTag === 'evasive') evasiveCount++;
                else if (r.articleTag === 'realistic') realisticCount++;
                if (r.acknowledged === 'Yes') ackCount++;
            });

            var band = this._band(total);
            var pct = Math.max(0, Math.min(100, Math.round((total / this.MAX_POINTS) * 100)));
            var last = h.length ? h[h.length - 1] : null;
            var tradition = (last && last.results && last.results.tradition) ||
                            (last && last.domainState && last.domainState.tradition) || '';

            var insights = [];
            if (evasiveCount >= 3) insights.push(this._t('sum_evasive'));
            if (pureCount >= 8) insights.push(this._t('sum_pure'));
            // realisticCount is the counter incremented above. The shipped code tested a
            // variable called realismCount, which was never declared: under strict mode
            // that threw a ReferenceError and killed the whole summary on every run.
            if (hybridCount >= 8 && consistency < 70) insights.push(this._t('sum_hybrid_lost'));
            if (ackCount >= 8) insights.push(this._t('sum_ack'));
            if (realisticCount === 0 && hybridCount === 0) insights.push(this._t('sum_no_realistic'));
            if (insights.length === 0) insights.push(this._t('sum_balanced'));

            var r1 = function(v) { return Math.round(v * 10) / 10; };
            // overallScore is the field the reporting layer reads; composite, totalScore
            // and score are the documented fallbacks and all carry the same 0-100 number.
            return {
                overallScore: pct,
                composite: pct,
                totalScore: pct,
                score: pct,
                rawPoints: r1(total),
                maxPoints: this.MAX_POINTS,
                consistency: r1(consistency),
                realism: r1(realism),
                honesty: r1(honesty),
                periodsPlayed: h.length,
                tradition: tradition,
                traditionLabel: tradition ? this._traditionLabel(tradition) : '',
                pureCount: pureCount,
                realisticCount: realisticCount,
                hybridCount: hybridCount,
                evasiveCount: evasiveCount,
                ackCount: ackCount,
                performance: band.id,
                performanceKey: band.key,
                performanceLabel: this._t(band.key),
                insights: insights
            };
        }

        _traditionLabel(id) {
            var entry = this.TRADITIONS[id];
            if (!entry) return id;
            return this._t('trad_' + id, entry.en);
        }

        // Without this the summary above is computed and thrown away: nothing in the
        // framework renders it. Everything interpolated here is escaped.
        formatCompletionMessage(summary) {
            var s = summary || {};
            var esc = this._esc.bind(this);
            var html = '<div class="aguarales-debrief">';
            html += '<div class="aguarales-debrief-score">' + esc(s.overallScore || 0) + '<span>/100</span></div>';
            html += '<div class="aguarales-debrief-band">' + esc(s.performanceLabel || '') + '</div>';
            html += '<div class="aguarales-debrief-raw">' + esc(this._t('debrief_raw')) + ' ' +
                    esc(s.rawPoints || 0) + ' / ' + esc(s.maxPoints || this.MAX_POINTS) + '</div>';
            if (s.traditionLabel) {
                html += '<div class="aguarales-debrief-trad"><strong>' + esc(this._t('tradition_label')) +
                        ':</strong> ' + esc(s.traditionLabel) + '</div>';
            }
            html += '<table class="aguarales-debrief-table"><tbody>';
            var rows = [
                [this._t('consistency_label'), s.consistency],
                [this._t('realism_label'), s.realism],
                [this._t('honesty_label'), s.honesty],
                [this._t('tag_pure'), s.pureCount],
                [this._t('tag_realistic'), s.realisticCount],
                [this._t('tag_hybrid'), s.hybridCount],
                [this._t('tag_evasive'), s.evasiveCount],
                [this._t('debrief_ack_count'), s.ackCount + ' / ' + (s.periodsPlayed || 0)]
            ];
            rows.forEach(function(r) {
                html += '<tr><th scope="row">' + esc(r[0]) + '</th><td>' + esc(r[1]) + '</td></tr>';
            });
            html += '</tbody></table>';
            var ins = s.insights || [];
            if (ins.length) {
                html += '<h4>' + esc(this._t('debrief_insights')) + '</h4><ul>';
                ins.forEach(function(t) { html += '<li>' + esc(t) + '</li>'; });
                html += '</ul>';
            }
            html += '</div>';
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.articleTag === 'evasive') return window.mySimulation.t('hint_evasive');
            if (results.articleTag === 'pure' && results.acknowledged === 'No' && results.round >= 2) return window.mySimulation.t('hint_pure_no_ack');
            if (results.articleTag === 'hybrid' && results.round === 1) return window.mySimulation.t('hint_hybrid_early');
            if (results.question === 'Q3') return window.mySimulation.t('hint_q3');
            return null;
        }

